@unless ($batch->isFinished())
    <section class="rounded-2xl border border-blue-200 bg-blue-50/70 p-5 dark:border-blue-900/70 dark:bg-blue-950/20" x-data="importBatchProgress({ statusUrl: @js(route('imports.status', $batch)), status: @js($batch->status), total: {{ (int) $batch->total_rows }}, success: {{ (int) $batch->success_rows }}, failed: {{ (int) $batch->failed_rows }}, processed: {{ $batch->processedRows() }}, percentage: {{ $batch->progressPercentage() }}, finished: false, reloadOnFinish: true })" x-init="start()">
        <div class="flex items-start justify-between gap-4"><div><p class="text-[10px] font-extrabold uppercase tracking-[.14em] text-blue-600 dark:text-blue-300">Progres antrean</p><h2 class="mt-1 text-sm font-extrabold text-ink-900 dark:text-white" x-text="statusLabel"></h2><p class="mt-1 text-xs text-ink-500 dark:text-ink-400" x-text="total ? `${processed} dari ${total} baris sudah diperiksa` : 'File sedang dibuka dan struktur kolom sedang diperiksa'"></p></div><strong class="text-2xl font-extrabold tabular-nums text-blue-700 dark:text-blue-300" x-text="`${percentage}%`"></strong></div>
        <div class="mt-4 h-2.5 overflow-hidden rounded-full bg-white dark:bg-ink-800"><div class="h-full rounded-full bg-blue-500 transition-all duration-500" :style="`width:${percentage}%`"></div></div>
        <div class="mt-3 flex flex-wrap items-center justify-between gap-2 text-[10px] text-ink-500 dark:text-ink-400"><span>Halaman hasil akan terbuka otomatis ketika proses selesai.</span><span x-show="pollError" x-cloak class="font-bold text-amber-600 dark:text-amber-300">Koneksi status tertunda · mencoba kembali</span></div>
    </section>
@endunless
